'use client';

import type { CSSProperties } from 'react';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { countOf } from '@/registry/ndeko/lib/words';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { AppSidebar, rowsOf } from './app-sidebar';
import { ChatHeader } from './chat-header';
import { Composer } from './composer';
import {
  BRAND,
  chatOf,
  DECLINED_LINE,
  LIVE_ID,
  LIVE_TITLE,
  NEW_CHAT_TITLE,
  NEW_ID,
  SOURCES,
  STOPPED_LINE,
} from './data';
import { RunDetails } from './run-details';
import {
  INITIAL,
  isBusy,
  isOver,
  isReadOnly,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  sendableTextOf,
  type ChatState,
  type Decision,
} from './session';
import { Thread } from './thread';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The width of the `@3xl` container variant: under it the chats live in a sheet. */
const SIDEBAR_SHEET_BELOW_REM = 48;

/** The width of the `@6xl` container variant: under it the run details live in a sheet. */
const DETAILS_SHEET_BELOW_REM = 72;

const SIDEBAR_WIDTH = '16rem';

const PANEL_WIDTH = '21rem';

type LayoutStyle = CSSProperties & {
  '--sidebar-w': string;
  '--panel-w': string;
};

function widthOf(isShown: boolean, width: string) {
  if (isShown) {
    return width;
  }
  return '0rem';
}

function layoutStyleOf(isSidebarShown: boolean, isPanelShown: boolean) {
  const style: LayoutStyle = {
    '--sidebar-w': widthOf(isSidebarShown, SIDEBAR_WIDTH),
    '--panel-w': widthOf(isPanelShown, PANEL_WIDTH),
  };
  return style;
}

function titleOf(state: ChatState) {
  if (state.activeId === LIVE_ID) {
    if (state.question === null) {
      return NEW_CHAT_TITLE;
    }
    return LIVE_TITLE;
  }
  if (state.activeId === NEW_ID) {
    return NEW_CHAT_TITLE;
  }
  return chatOf(state.activeId).title;
}

function placeholderOf(state: ChatState) {
  if (isReadOnly(state)) {
    return 'Start a new chat to write';
  }
  if (state.activeId === NEW_ID) {
    return 'Message Quenby';
  }
  const { stage } = state;
  if (stage === 'idle') {
    return 'Ask about a shipment';
  }
  if (stage === 'asking') {
    return 'Allow or deny the request above';
  }
  if (isOver(stage)) {
    return 'Ask a follow-up';
  }
  return 'Quenby is working';
}

function announcementOf(state: ChatState) {
  const { stage } = state;
  if (stage === 'thinking') {
    return 'Quenby is thinking';
  }
  if (stage === 'asking') {
    return 'Quenby asks to read the forwarder rate sheet. Allow or deny it';
  }
  if (stage === 'answering') {
    return 'Quenby is writing the answer';
  }
  if (stage === 'done') {
    return `The answer is ready, with ${countOf(SOURCES.length, 'source')}`;
  }
  if (stage === 'declined') {
    return DECLINED_LINE;
  }
  if (stage === 'stopped') {
    return STOPPED_LINE;
  }
  return '';
}

function emptyLineOf(state: ChatState) {
  if (state.activeId === LIVE_ID) {
    return 'The plan, the tool calls and the cost of the run show here once you ask a question.';
  }
  return 'Nothing runs in this chat. The details of a run show here when the assistant works.';
}

/** Nothing calls a network. A real assistant plugs in here: what a person sends, the answer to the request, and Stop. */
export type Application08Props = {
  onSend?: (text: string) => void;
  onApprove?: () => void;
  onDeny?: () => void;
  onStop?: () => void;
};

export default function Application08({
  onSend,
  onApprove,
  onDeny,
  onStop,
}: Application08Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const hasSidebarSheet = useIsNarrow(ref, SIDEBAR_SHEET_BELOW_REM);
  const hasDetailsSheet = useIsNarrow(ref, DETAILS_SHEET_BELOW_REM);
  const { stage } = state;
  const isLiveChat = state.activeId === LIVE_ID;
  const hasRun = isLiveChat && state.question !== null;
  const sendableText = sendableTextOf(state);
  const canSend = sendableText !== null;
  const showsStop = isLiveChat && isBusy(stage);
  const canReplay = isFinished && !isAutoplaying;
  const isSidebarSheetShown = hasSidebarSheet && state.isSidebarSheetOpen;
  const isDetailsSheetShown = hasDetailsSheet && state.isDetailsSheetOpen;
  const isBehindSheet = isSidebarSheetShown || isDetailsSheetShown;
  const isSidebarShown = !state.isSidebarCollapsed;
  const isPanelShown = state.isPanelOpen && !hasDetailsSheet;
  const message = spokenUnless(isAutoplaying, announcementOf(state));
  const layoutStyle = layoutStyleOf(isSidebarShown, isPanelShown);
  const canShowDetails = hasDetailsSheet || !isPanelShown;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function send() {
    if (sendableText === null) {
      return;
    }
    act({ type: 'sent' });
    onSend?.(sendableText);
  }

  function stop() {
    act({ type: 'stopped' });
    onStop?.();
  }

  /** The two buttons leave with the request, so the focus goes to what replaces them: the line that says what was decided. */
  function decide(decision: Decision) {
    act({ type: 'decided', decision });
    focusLater('[data-request]');
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    onApprove?.();
  }

  function toggleSidebar() {
    if (hasSidebarSheet) {
      act({ type: 'sidebarSheet', isOpen: true });
      focusLater('[data-sheet-close="chats"]');
      return;
    }
    act({ type: 'sidebarCollapsed', isCollapsed: !state.isSidebarCollapsed });
  }

  function closeSidebarSheet() {
    act({ type: 'sidebarSheet', isOpen: false });
    focusLater('[data-sidebar-toggle]');
  }

  function openDetailsSheet() {
    act({ type: 'detailsSheet', isOpen: true });
    focusLater('[data-sheet-close="details"]');
  }

  function closeDetailsSheet() {
    act({ type: 'detailsSheet', isOpen: false });
    focusLater('[data-details-toggle]');
  }

  function toggleDetails() {
    if (hasDetailsSheet) {
      openDetailsSheet();
      return;
    }
    act({ type: 'panel', isOpen: !state.isPanelOpen });
  }

  function showDetails() {
    if (hasDetailsSheet) {
      openDetailsSheet();
      return;
    }
    act({ type: 'panel', isOpen: true });
  }

  function openChat(id: string) {
    act({ type: 'chatOpened', id });
    focusLater('[data-composer-field]');
  }

  function startNewChat() {
    act({ type: 'newChat' });
    focusLater('[data-composer-field]');
  }

  function suggest(text: string) {
    act({ type: 'typed', text });
    focusLater('[data-composer-field]');
  }

  const sidebar = {
    rows: rowsOf(state),
    activeId: state.activeId,
    search: state.search,
    onSearch: (text: string) => act({ type: 'searched', text }),
    onOpen: openChat,
    onNewChat: startNewChat,
  };

  const details = {
    stage,
    plan: state.plan,
    calls: state.calls,
    tokens: state.tokens,
    costUsd: state.costUsd,
    runModel: state.runModel,
    hasRun,
    emptyLine: emptyLineOf(state),
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-sidebar text-foreground @container min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] overflow-hidden'>
          <div
            inert={isBehindSheet}
            style={layoutStyle}
            className='grid min-h-0 min-w-0 flex-1 grid-cols-1 transition-[grid-template-columns] duration-300 ease-(--ease-drawer) @3xl:grid-cols-[var(--sidebar-w)_minmax(0,1fr)] @3xl:p-2 @6xl:grid-cols-[var(--sidebar-w)_minmax(0,1fr)_var(--panel-w)]'
          >
            <aside
              aria-label='Chats'
              inert={state.isSidebarCollapsed}
              className='hidden min-h-0 min-w-0 overflow-hidden @3xl:block'
            >
              <div className='h-full w-64 pe-2'>
                {!hasSidebarSheet && <AppSidebar {...sidebar} />}
              </div>
            </aside>
            <main className='bg-background @3xl:hairline-ring @3xl:ring-border flex min-h-0 min-w-0 flex-col overflow-clip @3xl:rounded-xl @3xl:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
              <ChatHeader
                title={titleOf(state)}
                stage={stage}
                model={state.model}
                hasSidebarSheet={hasSidebarSheet}
                hasDetailsSheet={hasDetailsSheet}
                isSidebarShown={isSidebarShown}
                isDetailsShown={isPanelShown}
                canReplay={canReplay}
                onToggleSidebar={toggleSidebar}
                onToggleDetails={toggleDetails}
                onModelChange={(model) => act({ type: 'modelSet', model })}
                onReplay={restart}
              />
              <Thread
                state={state}
                pressed={pressed}
                isActive={isInView}
                onDecide={decide}
                canShowDetails={canShowDetails}
                onShowDetails={showDetails}
                onSuggest={suggest}
              />
              <div className='mx-auto w-full max-w-2xl shrink-0 px-4 pb-4'>
                <Composer
                  draft={state.draft}
                  placeholder={placeholderOf(state)}
                  canSend={canSend}
                  isRunning={showsStop}
                  isReadOnly={isReadOnly(state)}
                  isSendPressed={pressed === 'send'}
                  onDraftChange={(text) => act({ type: 'typed', text })}
                  onSend={send}
                  onStop={stop}
                />
              </div>
            </main>
            <aside
              aria-label='Run details'
              inert={!state.isPanelOpen}
              className='hidden min-h-0 min-w-0 overflow-hidden @6xl:block'
            >
              <div className='h-full w-[21rem] ps-2'>
                <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex h-full min-h-0 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
                  {!hasDetailsSheet && (
                    <RunDetails {...details} className='w-full' />
                  )}
                </div>
              </div>
            </aside>
          </div>

          <InlineSheet
            name='chats'
            label={`${BRAND.name} chats`}
            closeLabel='Close the chats'
            side='start'
            isOpen={isSidebarSheetShown}
            className='@3xl:hidden'
            panelClassName='bg-sidebar gap-1 p-3'
            onClose={closeSidebarSheet}
          >
            {hasSidebarSheet && <AppSidebar {...sidebar} />}
          </InlineSheet>
          <InlineSheet
            name='details'
            label='Run details'
            closeLabel='Close the run details'
            side='bottom'
            closer='grip'
            isOpen={isDetailsSheetShown}
            className='@6xl:hidden'
            panelClassName='h-[80%] px-4 pb-4'
            onClose={closeDetailsSheet}
          >
            {hasDetailsSheet && <RunDetails {...details} className='flex-1' />}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PlusIcon, SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { wordsOf } from '@/registry/ndeko/lib/words';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { Input } from '@/registry/ndeko/ui/input';

import {
  BRAND,
  CHATS,
  DAYS,
  LIVE_ID,
  LIVE_TITLE,
  NEW_ID,
  type Day,
} from './data';
import { isBusy, type ChatState } from './session';

const TITLE_WORDS = 5;

export type RowStatus = 'running' | 'waiting';

export type SidebarRow = {
  id: string;
  title: string;
  day: Day;
  status?: RowStatus;
};

function shortTitleOf(text: string) {
  const words = wordsOf(text);
  const kept = words.slice(0, TITLE_WORDS);
  return kept.join(' ');
}

function liveStatusOf(state: ChatState): RowStatus | undefined {
  if (state.stage === 'asking') {
    return 'waiting';
  }
  if (isBusy(state.stage)) {
    return 'running';
  }
  return undefined;
}

/** The chat the person is in sits first of its day: the new chat, then the one that holds the run, then the older ones. */
export function rowsOf(state: ChatState): SidebarRow[] {
  const rows: SidebarRow[] = [];
  if (state.newLines.length > 0) {
    const title = shortTitleOf(state.newLines[0]);
    rows.push({ id: NEW_ID, title, day: 'Today' });
  }
  if (state.question !== null) {
    const status = liveStatusOf(state);
    rows.push({ id: LIVE_ID, title: LIVE_TITLE, day: 'Today', status });
  }
  for (const chat of CHATS) {
    rows.push({ id: chat.id, title: chat.title, day: chat.day });
  }
  return rows;
}

function needleOf(query: string) {
  const trimmed = query.trim();
  return trimmed.toLowerCase();
}

function matchesQuery(title: string, query: string) {
  const needle = needleOf(query);
  if (needle === '') {
    return true;
  }
  const lowered = title.toLowerCase();
  return lowered.includes(needle);
}

function HighlightedTitle({ title, query }: { title: string; query: string }) {
  const needle = needleOf(query);
  const lowered = title.toLowerCase();
  const index = lowered.indexOf(needle);
  const hasMatch = needle !== '' && index >= 0;
  if (!hasMatch) {
    return <>{title}</>;
  }
  const end = index + needle.length;

  return (
    <>
      {title.slice(0, index)}
      <mark className='bg-primary/15 rounded-[3px] text-inherit'>
        {title.slice(index, end)}
      </mark>
      {title.slice(end)}
    </>
  );
}

const ROW =
  'hover:bg-foreground/5 focus-visible:ring-ring/25 flex h-8 w-full min-w-0 cursor-pointer items-center gap-2 rounded-md px-2 text-start text-[13px] outline-none transition-colors duration-150 focus-visible:ring-[3px] focus-visible:ring-inset';

function rowToneOf(isActive: boolean) {
  if (isActive) {
    return 'bg-foreground/[0.07] font-medium';
  }
  return undefined;
}

function currentOf(isActive: boolean): 'page' | undefined {
  if (isActive) {
    return 'page';
  }
  return undefined;
}

const STATUS_DOT: Record<RowStatus, string> = {
  running: 'bg-info',
  waiting: 'bg-warning',
};

const STATUS_WORD: Record<RowStatus, string> = {
  running: 'Running',
  waiting: 'Waiting on you',
};

type ChatRowProps = {
  row: SidebarRow;
  query: string;
  isActive: boolean;
  onOpen: (id: string) => void;
};

function ChatRow({ row, query, isActive, onOpen }: ChatRowProps) {
  function open() {
    onOpen(row.id);
  }

  return (
    <button
      type='button'
      aria-current={currentOf(isActive)}
      onClick={open}
      className={cn(ROW, rowToneOf(isActive))}
    >
      <span className='min-w-0 flex-1 truncate'>
        <HighlightedTitle title={row.title} query={query} />
      </span>
      {row.status && (
        <span className='flex shrink-0 items-center'>
          <span
            aria-hidden='true'
            className={cn('size-1.5 rounded-full', STATUS_DOT[row.status])}
          />
          <span className='sr-only'>{STATUS_WORD[row.status]}</span>
        </span>
      )}
    </button>
  );
}

type SearchFieldProps = {
  value: string;
  onChange: (text: string) => void;
};

function SearchField({ value, onChange }: SearchFieldProps) {
  const hasQuery = value !== '';

  function clear() {
    onChange('');
  }

  /** The first Escape empties the field. A second one is left to the sheet, which closes. */
  function clearFromKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Escape' || !hasQuery) {
      return;
    }
    event.stopPropagation();
    clear();
  }

  return (
    <div className='relative'>
      <SearchIcon
        aria-hidden='true'
        className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-3.5 -translate-y-1/2'
      />
      <Input
        type='search'
        size='sm'
        aria-label='Search chats'
        placeholder='Search chats'
        value={value}
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={clearFromKeys}
        className='ps-8 pe-7'
      />
      {hasQuery && (
        <button
          type='button'
          aria-label='Clear the search'
          onClick={clear}
          className='text-muted-foreground hover:bg-foreground/[0.07] hover:text-foreground focus-visible:ring-ring/25 absolute end-1.5 top-1/2 flex size-5 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]'
        >
          <XIcon className='size-3' />
        </button>
      )}
    </div>
  );
}

type AppSidebarProps = {
  rows: SidebarRow[];
  activeId: string;
  search: string;
  onSearch: (text: string) => void;
  onOpen: (id: string) => void;
  onNewChat: () => void;
  className?: string;
};

export function AppSidebar({
  rows,
  activeId,
  search,
  onSearch,
  onOpen,
  onNewChat,
  className,
}: AppSidebarProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const shown = rows.filter((row) => matchesQuery(row.title, search));
  const hasNoMatch = shown.length === 0;

  function clearSearch() {
    onSearch('');
  }

  return (
    <div className={cn('flex min-h-0 w-full flex-col gap-3', className)}>
      <div className='flex flex-col gap-2'>
        <div className='flex h-9 items-center gap-2 px-1.5'>
          <CompanyMark seed={BRAND.name} className='size-6 rounded-md' />
          <span className='text-[13px] font-semibold'>{BRAND.name}</span>
        </div>
        <Button
          type='button'
          variant='outline'
          data-new-chat
          onClick={onNewChat}
          className='w-full justify-start'
        >
          <PlusIcon />
          New chat
        </Button>
        <SearchField value={search} onChange={onSearch} />
      </div>
      <nav
        aria-label='Chats'
        className='-mx-1 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-1'
      >
        {DAYS.map((day) => {
          const ofDay = shown.filter((row) => row.day === day);
          if (ofDay.length === 0) {
            return null;
          }
          return (
            <section key={day} className='flex flex-col gap-0.5'>
              <h2 className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
                {day}
              </h2>
              <ul className='flex flex-col'>
                <AnimatePresence initial={false}>
                  {ofDay.map((row) => (
                    <motion.li
                      key={row.id}
                      className='-mx-1 overflow-hidden px-1'
                      {...rowPresence}
                    >
                      <ChatRow
                        row={row}
                        query={search}
                        isActive={row.id === activeId}
                        onOpen={onOpen}
                      />
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ul>
            </section>
          );
        })}
        {hasNoMatch && (
          <div className='flex flex-col items-start gap-1.5 px-2 text-xs'>
            <p className='text-muted-foreground'>
              No chat matches &quot;{search.trim()}&quot;
            </p>
            <Button
              type='button'
              variant='link'
              size='sm'
              onClick={clearSearch}
              className='h-6 px-0'
            >
              Clear the search
            </Button>
          </div>
        )}
      </nav>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CircleXIcon } from '@/registry/ndeko/lib/icons';
import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { Spinner } from '@/registry/ndeko/ui/spinner';
import { Wash } from '@/registry/ndeko/ui/wash';

import { DECLINED_LINE, FORWARDER_CONTACT, REQUEST } from './data';
import type { Decision, RequestView } from './session';

type RequestBodyProps = {
  pressed: string | null;
  onDecide: (decision: Decision) => void;
};

function RequestBody({ pressed, onDecide }: RequestBodyProps) {
  const titleId = useId();
  const keysId = useId();

  function allow() {
    onDecide('approved');
  }

  function deny() {
    onDecide('denied');
  }

  function decideFromKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      deny();
      return;
    }
    const isOnCard = event.target === event.currentTarget;
    const isEnter = event.key === 'Enter';
    if (isEnter && isOnCard) {
      event.preventDefault();
      allow();
    }
  }

  return (
    <div
      role='group'
      tabIndex={0}
      aria-labelledby={titleId}
      aria-describedby={keysId}
      onKeyDown={decideFromKeys}
      className='focus-visible:ring-ring/25 relative isolate flex flex-col gap-3 rounded-xl p-3 outline-none focus-visible:ring-[3px] focus-visible:ring-inset'
    >
      <Wash color='var(--warning)' />
      <div className='flex items-center gap-2.5'>
        <BrandTile brand='googledrive' size='lg' title='Google Drive' />
        <div className='flex min-w-0 flex-1 flex-col leading-tight'>
          <h2 id={titleId} className='text-sm font-medium'>
            Read a file shared with you
          </h2>
          <span className='text-muted-foreground truncate text-xs'>
            {REQUEST.file}
          </span>
        </div>
        <Badge variant='warning' className='hidden @md:inline-flex'>
          Waiting on you
        </Badge>
      </div>
      <dl className='bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-2.5 text-xs'>
        <div className='flex items-center gap-2'>
          <dt className='text-muted-foreground w-14 shrink-0'>Owner</dt>
          <dd className='flex min-w-0 items-center gap-1.5'>
            <Avatar seed={FORWARDER_CONTACT.name} className='size-5' />
            <span className='min-w-0 truncate'>
              {FORWARDER_CONTACT.name}
              <span className='text-muted-foreground'>
                , {FORWARDER_CONTACT.role}
              </span>
            </span>
          </dd>
        </div>
        <div className='flex gap-2'>
          <dt className='text-muted-foreground w-14 shrink-0'>Access</dt>
          <dd className='min-w-0'>{REQUEST.access}</dd>
        </div>
        <div className='flex gap-2'>
          <dt className='text-muted-foreground w-14 shrink-0'>Why</dt>
          <dd className='min-w-0'>{REQUEST.reason}</dd>
        </div>
      </dl>
      <div className='flex flex-wrap items-center gap-2'>
        <Button
          type='button'
          size='sm'
          onClick={allow}
          className={pressedSolidOf(pressed === 'allow')}
        >
          Allow
          <Kbd className='ms-0.5'>Enter</Kbd>
        </Button>
        <Button type='button' size='sm' variant='outline' onClick={deny}>
          Deny
          <Kbd className='ms-0.5'>Esc</Kbd>
        </Button>
        <span id={keysId} className='sr-only'>
          Enter allows, Escape denies
        </span>
      </div>
    </div>
  );
}

function ResultGlyph({ view }: { view: RequestView }) {
  if (view === 'reading') {
    return <Spinner aria-hidden='true' />;
  }
  if (view === 'read') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  return <CircleXIcon className='text-muted-foreground size-4 shrink-0' />;
}

function resultLineOf(view: RequestView) {
  if (view === 'reading') {
    return 'Reading the rate sheet';
  }
  if (view === 'read') {
    return 'Allowed. The rate sheet was read, with two quotes in it';
  }
  if (view === 'denied') {
    return DECLINED_LINE;
  }
  return 'Not answered. The run was stopped before the sheet was read';
}

function ResultLine({ view }: { view: RequestView }) {
  return (
    <div className='flex min-h-11 items-start gap-2.5 p-3 text-[13px] leading-5'>
      <Swap swapKey={view} className='mt-px'>
        <ResultGlyph view={view} />
      </Swap>
      <p
        key={view}
        className='min-w-0 transition-opacity duration-300 starting:opacity-0'
      >
        {resultLineOf(view)}
      </p>
    </div>
  );
}

function viewKeyOf(isAsking: boolean) {
  if (isAsking) {
    return 'request';
  }
  return 'result';
}

type ApprovalCardProps = RequestBodyProps & {
  view: RequestView;
};

export function ApprovalCard({ view, pressed, onDecide }: ApprovalCardProps) {
  const fade = fadePresence();
  const isAsking = view === 'asking';

  return (
    <section
      data-request
      tabIndex={-1}
      aria-label='Request to read the rate sheet'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-opacity duration-300 outline-none starting:opacity-0'
    >
      <AnimatedSize>
        <AnimatePresence initial={false} mode='popLayout'>
          <motion.div key={viewKeyOf(isAsking)} {...fade}>
            {isAsking && <RequestBody pressed={pressed} onDecide={onDecide} />}
            {!isAsking && <ResultLine view={view} />}
          </motion.div>
        </AnimatePresence>
      </AnimatedSize>
    </section>
  );
}

