} from './data';

export type Stage =
  | 'idle'
  | 'thinking'
  | 'working'
  | 'asking'
  | 'answering'
  | 'done'
  | 'declined'
  | 'stopped';

export type Decision = 'approved' | 'denied';

export type StepStatus =
  'upcoming' | 'running' | 'waiting' | 'done' | 'skipped';

export type PlanRun = {
  id: StepId;
