};

export type ChatState = {
  activeId: string;
  draft: string;
  model: ModelId;
  runModel: ModelId;
  question: string | null;
  followUps: string[];
  newLines: string[];
  stage: Stage;
  stoppedFrom: Stage | null;
  decision: Decision | null;
  plan: PlanRun[];
  calls: CallRun[];
  tokens: Tokens;
  costUsd: number;
  startedAt?: number;
  thoughtEndedAt?: number;
  endedAt?: number;
  demoLitSource: number | null;
  isPanelOpen: boolean;
  isDetailsSheetOpen: boolean;
  isSidebarCollapsed: boolean;
  isSidebarSheetOpen: boolean;
  search: string;
};

export type ChatAction =
  | { type: 'typed'; text: string }
  | { type: 'sent' }
  | { type: 'modelSet'; model: ModelId }
  | { type: 'thoughtDone' }
  | { type: 'stepStarted'; id: StepId }
  | { type: 'stepDone'; id: StepId }
  | { type: 'asked' }
  | { type: 'decided'; decision: Decision }
  | { type: 'answering' }
  | { type: 'answered' }
  | { type: 'stopped' }
  | { type: 'lit'; source: number | null }
  | { type: 'panel'; isOpen: boolean }
  | { type: 'detailsSheet'; isOpen: boolean }
  | { type: 'sidebarCollapsed'; isCollapsed: boolean }
  | { type: 'sidebarSheet'; isOpen: boolean }
  | { type: 'searched'; text: string }
  | { type: 'chatOpened'; id: string }
  | { type: 'newChat' }
  | { type: 'batch'; actions: ChatAction[] };

type Step = SessionStep<ChatState, ChatAction>;

export const INITIAL: ChatState = {
  activeId: LIVE_ID,
  draft: '',
  model: STARTING_MODEL,
  runModel: STARTING_MODEL,
  question: null,
  followUps: [],
  newLines: [],
  stage: 'idle',
  stoppedFrom: null,
  decision: null,
  plan: [],
  calls: [],
  tokens: { input: 0, output: 0 },
  costUsd: 0,
  demoLitSource: null,
  isPanelOpen: true,
  isDetailsSheetOpen: false,
  isSidebarCollapsed: false,
  isSidebarSheetOpen: false,
  search: '',
};

const BUSY_STAGES: Stage[] = ['thinking', 'working', 'asking', 'answering'];

const OVER_STAGES: Stage[] = ['done', 'declined', 'stopped'];

const WORKING_STAGES: Stage[] = ['working', 'answering'];

export function isBusy(stage: Stage) {
  return BUSY_STAGES.includes(stage);
}

export function isOver(stage: Stage) {
  return OVER_STAGES.includes(stage);
}

const WRITABLE_CHATS = [LIVE_ID, NEW_ID];

export function isReadOnly(state: ChatState) {
  return !WRITABLE_CHATS.includes(state.activeId);
}

/** The answer shows from its first word, and stays when the run was stopped halfway through it. */
export function showsAnswerOf(state: ChatState) {
  if (state.stage === 'stopped') {
    return state.stoppedFrom === 'answering';
  }
  const answerStages: Stage[] = ['answering', 'done'];
  return answerStages.includes(state.stage);
}

export type RequestView =
  'none' | 'asking' | 'reading' | 'read' | 'denied' | 'unanswered';

export function requestViewOf(state: ChatState): RequestView {
  if (state.stage === 'asking') {
    return 'asking';
  }
  if (state.decision === 'denied') {
    return 'denied';
  }
  if (state.decision === 'approved') {
    const call = state.calls.find((candidate) => candidate.id === 'rates');
    if (call?.status === 'done') {
      return 'read';
    }
    return 'reading';
  }
  if (state.stoppedFrom === 'asking') {
    return 'unanswered';
  }
  return 'none';
}

function trimmedQuestionOf(draft: string) {
  const trimmed = draft.trim();
  if (trimmed === '') {
    return null;
  }
  const isUnfinishedDemo = QUESTION.startsWith(trimmed);
  if (isUnfinishedDemo) {
    return QUESTION;
  }
  return trimmed;
}

/**
 * What Send would post now: the first question of the live chat (a person who takes over halfway
 * through the demonstration question sends the whole of it), a follow-up once the run is over, a
 * line in a new chat. Null while the agent works or when there is nothing to send.
 */
export function sendableTextOf(state: ChatState) {
  if (isReadOnly(state)) {
    return null;
  }
  if (state.activeId === NEW_ID) {
    const line = state.draft.trim();
    if (line === '') {
      return null;
    }
    return line;
  }
  if (state.question === null) {
    return trimmedQuestionOf(state.draft);
  }
  const text = state.draft.trim();
  const canFollowUp = isOver(state.stage) && text !== '';
  if (canFollowUp) {
    return text;
  }
  return null;
}

function sent(state: ChatState, now: number): ChatState {
  const text = sendableTextOf(state);
  if (text === null) {
    return state;
  }
  if (state.activeId === NEW_ID) {
    return { ...state, draft: '', newLines: [...state.newLines, text] };
  }
  if (state.question === null) {
    return {
      ...state,
      draft: '',
      question: text,
      runModel: state.model,
      stage: 'thinking',
      startedAt: now,
    };
  }
  return { ...state, draft: '', followUps: [...state.followUps, text] };
}

function costOf(model: ModelId, tokens: Tokens) {
  const total = tokens.input + tokens.output;
  const thousands = total / 1000;
  return thousands * modelOf(model).usdPerThousandTokens;
}

function withUsage(state: ChatState, usage: Tokens): ChatState {
  const tokens = {
    input: state.tokens.input + usage.input,
    output: state.tokens.output + usage.output,
  };
  const costUsd = state.costUsd + costOf(state.runModel, usage);
  return { ...state, tokens, costUsd };
}

function thoughtDone(state: ChatState, now: number): ChatState {
  if (state.stage !== 'thinking') {
    return state;
  }
  const plan: PlanRun[] = PLAN.map((seed) => ({
    id: seed.id,
    status: 'upcoming',
  }));
  const thought: ChatState = {
    ...state,
    plan,
    stage: 'working',
    thoughtEndedAt: now,
  };
  return withUsage(thought, THOUGHT_USAGE);
}

function planRunOf(state: ChatState, id: StepId) {
  return state.plan.find((run) => run.id === id);
}

function hasCall(state: ChatState, id: CallId) {
  return state.calls.some((call) => call.id === id);
}

function patchedPlan(
  state: ChatState,
  id: StepId,
  change: (run: PlanRun) => PlanRun
) {
  return state.plan.map((run) => {
    if (run.id !== id) {
      return run;
    }
    return change(run);
  });
}

function patchedCalls(
  state: ChatState,
  id: CallId,
  change: (call: CallRun) => CallRun
) {
  return state.calls.map((call) => {
    if (call.id !== id) {
      return call;
    }
    return change(call);
  });
}

function stepStarted(state: ChatState, id: StepId, now: number): ChatState {
  const isWorking = WORKING_STAGES.includes(state.stage);
  const run = planRunOf(state, id);
  const isUpcoming = run?.status === 'upcoming';
  if (!isWorking || !isUpcoming) {
    return state;
  }
  const plan = patchedPlan(state, id, (current) => ({
    ...current,
    status: 'running',
    startedAt: now,
  }));
  const callId = planSeedOf(id).callId;
  if (callId === undefined) {
    return { ...state, plan };
  }
  if (hasCall(state, callId)) {
    return { ...state, plan };
  }
  const call: CallRun = { id: callId, status: 'running', startedAt: now };
  return { ...state, plan, calls: [...state.calls, call] };
}

function stepDone(state: ChatState, id: StepId, now: number): ChatState {
  const isWorking = WORKING_STAGES.includes(state.stage);
  const run = planRunOf(state, id);
  const isRunning = run?.status === 'running';
  if (!isWorking || !isRunning) {
    return state;
  }
  const plan = patchedPlan(state, id, (current) => ({
    ...current,
    status: 'done',
    endedAt: now,
  }));
  const callId = planSeedOf(id).callId;
  if (callId === undefined) {
    return { ...state, plan };
  }
  const calls = patchedCalls(state, callId, (current) => ({
    ...current,
    status: 'done',
    endedAt: now,
  }));
  const seed = callSeedOf(callId);
  const usage = { input: seed.inputTokens, output: seed.outputTokens };
  return withUsage({ ...state, plan, calls }, usage);
}

function asked(state: ChatState): ChatState {
  if (state.stage !== 'working') {
    return state;
  }
  const plan = patchedPlan(state, 'rates', (run) => ({
    ...run,
    status: 'waiting',
  }));
  const calls = patchedCalls(state, 'rates', (call) => ({
    ...call,
    status: 'waiting',
  }));
  return { ...state, stage: 'asking', plan, calls };
}

function skippedRest(state: ChatState, now: number): ChatState {
  const plan = state.plan.map((run) => {
    if (run.status === 'done') {
      return run;
    }
    const skipped: PlanRun = { ...run, status: 'skipped', endedAt: now };
    return skipped;
  });
  const calls = state.calls.map((call) => {
    if (call.status === 'done') {
      return call;
    }
    const skipped: CallRun = { ...call, status: 'skipped', endedAt: now };
    return skipped;
  });
  return { ...state, plan, calls, endedAt: now };
}

function decided(state: ChatState, decision: Decision, now: number): ChatState {
  if (state.stage !== 'asking') {
    return state;
  }
  if (decision === 'denied') {
    const declined: ChatState = { ...state, stage: 'declined', decision };
    return skippedRest(declined, now);
  }
  const plan = patchedPlan(state, 'rates', (run) => ({
    ...run,
    status: 'running',
  }));
  const calls = patchedCalls(state, 'rates', (call) => ({
    ...call,
    status: 'running',
  }));
  return { ...state, stage: 'working', decision, plan, calls };
}

function answering(state: ChatState): ChatState {
  if (state.stage !== 'working') {
    return state;
  }
  return { ...state, stage: 'answering' };
}

function answered(state: ChatState, now: number): ChatState {
  if (state.stage !== 'answering') {
    return state;
  }
  const finished: ChatState = { ...state, stage: 'done', endedAt: now };
  return withUsage(finished, ANSWER_USAGE);
}

function stopped(state: ChatState, now: number): ChatState {
  if (!isBusy(state.stage)) {
    return state;
  }
  const halted = skippedRest(state, now);
  const thoughtEndedAt = state.thoughtEndedAt ?? now;
  return {
    ...halted,
    stage: 'stopped',
    stoppedFrom: state.stage,
    thoughtEndedAt,
  };
}

function newChatTarget(state: ChatState) {
  if (state.question === null) {
    return LIVE_ID;
  }
  return NEW_ID;
}

function chatOpened(state: ChatState, id: string): ChatState {
  return { ...state, activeId: id, isSidebarSheetOpen: false };
}

export function applyAt(
  state: ChatState,
  action: ChatAction,
  now: number
): ChatState {
  switch (action.type) {
    case 'typed':
      return { ...state, draft: action.text };
    case 'sent':
      return sent(state, now);
    case 'modelSet':
      return { ...state, model: action.model };
    case 'thoughtDone':
      return thoughtDone(state, now);
    case 'stepStarted':
      return stepStarted(state, action.id, now);
    case 'stepDone':
      return stepDone(state, action.id, now);
    case 'asked':
      return asked(state);
    case 'decided':
      return decided(state, action.decision, now);
    case 'answering':
      return answering(state);
    case 'answered':
      return answered(state, now);
    case 'stopped':
      return stopped(state, now);
    case 'lit':
      return { ...state, demoLitSource: action.source };
    case 'panel':
      return { ...state, isPanelOpen: action.isOpen };
    case 'detailsSheet':
      return { ...state, isDetailsSheetOpen: action.isOpen };
    case 'sidebarCollapsed':
      return { ...state, isSidebarCollapsed: action.isCollapsed };
    case 'sidebarSheet':
      return { ...state, isSidebarSheetOpen: action.isOpen };
    case 'searched':
      return { ...state, search: action.text };
    case 'chatOpened':
      return chatOpened(state, action.id);
    case 'newChat':
      return chatOpened(state, newChatTarget(state));
    case 'batch': {
      let next = state;
      for (const inner of action.actions) {
        next = applyAt(next, inner, now);
      }
      return next;
    }
  }
}

export function reducer(state: ChatState, action: ChatAction) {
  return applyAt(state, action, Date.now());
}

function hasAsked(state: ChatState) {
  return state.question !== null;
}

/** Whoever answers the request, or a run that ended before it, leaves the stage `asking`. */
function hasDecided(state: ChatState) {
  return state.stage !== 'asking';
}

export const WORD_MS = 55;

export const ANSWER_WORD_MS = 45;

/** A stream is given a little longer than its words need, so its last word lands before the next step. */
const STREAM_MARGIN_MS = 200;

const KEY_MS = 40;

const DEMO_DECIDES_AFTER_MS = 2500;

const THOUGHT_MS = THOUGHT_WORDS.length * WORD_MS + STREAM_MARGIN_MS;

const ANSWER_MS = ANSWER_TOKENS.length * ANSWER_WORD_MS + STREAM_MARGIN_MS;

function typingSteps(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', text: typed },
  }));
}

function frame(after: number, actions: ChatAction[]): Step {
  return { after, action: { type: 'batch', actions } };
}

function started(id: StepId): ChatAction {
  return { type: 'stepStarted', id };
}

function done(id: StepId): ChatAction {
  return { type: 'stepDone', id };
}

function lit(after: number, source: number | null): Step {
  return { after, by: 'demo', action: { type: 'lit', source } };
}

function detailsSheet(after: number, isOpen: boolean): Step {
  return { after, by: 'demo', action: { type: 'detailsSheet', isOpen } };
}

/** On a narrow page the run details live in a sheet, which the demonstration opens and closes as a person would. */
const OPENING: Step[] = [
  {
    after: 900,
    by: 'demo',
    action: { type: 'modelSet', model: DEMO_MODEL },
  },
  ...typingSteps(QUESTION, 900),
  {
    after: 500,
    by: 'person',
    press: 'send',
    action: { type: 'sent' },
    isAnswered: hasAsked,
  },
  frame(THOUGHT_MS, [{ type: 'thoughtDone' }, started('booking')]),
  detailsSheet(700, true),
  frame(1200, [done('booking'), started('sailings')]),
  frame(1200, [done('sailings'), started('rates')]),
  detailsSheet(500, false),
  frame(700, [{ type: 'asked' }]),
];

const CLOSING: Step[] = [
  {
    after: DEMO_DECIDES_AFTER_MS,
    by: 'person',
    press: 'allow',
    action: { type: 'decided', decision: 'approved' },
    isAnswered: hasDecided,
  },
  frame(1400, [done('rates'), started('customs')]),
  frame(1200, [done('customs'), started('answer'), { type: 'answering' }]),
  frame(ANSWER_MS, [done('answer'), { type: 'answered' }]),
  lit(800, 1),
  lit(600, 2),
  lit(600, 3),
  lit(600, 4),
  lit(500, null),
];

export const SCRIPT: Step[] = [...OPENING, ...CLOSING];

const ASKED = restingOf(INITIAL, OPENING, applyAt);

/** Under reduced motion the run waits on its request: the steps before it are done and the request to read the rates shows. */
export const RESTING: ChatState = {
  ...ASKED,
  isDetailsSheetOpen: false,
  demoLitSource: null,
};

export const LOOP_AFTER_MS = 3600;

'use client';

import { useId, useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { elapsedOf, formatDuration } from '@/registry/ndeko/lib/agent-run';
import { BrainIcon, ChevronDownIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';
import { StreamedText } from '@/registry/ndeko/ui/streamed-text';

import { THOUGHT } from './data';
import { WORD_MS, type Stage } from './session';

function headlineOf(stage: Stage, duration: string) {
  if (stage === 'thinking') {
    return 'Thinking';
  }
  if (stage === 'stopped') {
    return `Stopped after ${duration}`;
  }
  return `Thought for ${duration}`;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

type ThinkingBlockProps = {
  stage: Stage;
  isActive: boolean;
  startedAt?: number;
  thoughtEndedAt?: number;
};

export function ThinkingBlock({
  stage,
  isActive,
  startedAt,
  thoughtEndedAt,
}: ThinkingBlockProps) {
  const [openChoice, setOpenChoice] = useState<boolean | null>(null);
  const [wasThinking, setWasThinking] = useState(stage === 'thinking');
  const panelId = useId();
  const isThinking = stage === 'thinking';
  const span = { startedAt, endedAt: thoughtEndedAt };
  const elapsed = elapsedOf(span, thoughtEndedAt ?? 0);
  const duration = formatDuration(elapsed);
  const headline = headlineOf(stage, duration);

  if (wasThinking !== isThinking) {
    setWasThinking(isThinking);
    setOpenChoice(null);
  }

  const isOpen = openChoice ?? isThinking;

  function toggle() {
    setOpenChoice(!isOpen);
  }

  return (
    <div className='bg-foreground/[0.03] dark:bg-foreground/[0.05] rounded-xl p-1.5'>
      <button
        type='button'
        aria-expanded={isOpen}
        aria-controls={panelId}
        onClick={toggle}
        className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 flex h-8 w-full cursor-pointer items-center gap-2 rounded-lg px-2 text-start text-[13px] outline-none focus-visible:ring-[3px]'
      >
        <BrainIcon className='text-muted-foreground size-4 shrink-0' />
        <span className='min-w-0 truncate font-medium'>
          <WordRoll text={headline} />
        </span>
        {isThinking && (
          <LiveDuration
            item={span}
            isRunning
            className='text-muted-foreground w-10 text-xs'
          />
        )}
        <ChevronDownIcon
          className={cn(
            'text-muted-foreground ms-auto size-3.5 shrink-0 transition-transform duration-200 ease-(--ease-out-strong)',
            chevronTurnOf(isOpen)
          )}
        />
      </button>
      <Fold open={isOpen} id={panelId}>
        <p className='text-muted-foreground px-2 pt-1.5 pb-2 text-[13px] leading-relaxed'>
          <StreamedText
            text={THOUGHT}
            isStreaming={isThinking}
            isActive={isActive}
            wordMs={WORD_MS}
          />
        </p>
      </Fold>
    </div>
  );
}

'use client';

import { useFollowBottom } from '@/registry/ndeko/hooks/use-follow-bottom';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { ApprovalCard } from './approval-card';
import { CitedAnswer } from './cited-answer';
import {
  ASSISTANT,
  chatOf,
  FOLLOW_UP_REPLY,
  LIVE_ID,
  LIVE_SUGGESTIONS,
  NEW_ID,
  NEW_SUGGESTIONS,
  type ChatLine,
} from './data';
import {
  requestViewOf,
  showsAnswerOf,
  type ChatState,
  type Decision,
} from './session';
import { ThinkingBlock } from './thinking-block';
import { WorkLine } from './work-line';

function AssistantTile() {
  const color = seriesColorOf(ASSISTANT.series);

  return <MeshTile seed={ASSISTANT.name} color={color} size='lg' />;
}

function PersonBubble({ text }: { text: string }) {
  return (
    <p className='bg-foreground/[0.06] max-w-[85%] self-end rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed'>
      {text}
    </p>
  );
}

function AssistantLine({ text }: { text: string }) {
  return (
    <div className='flex items-start gap-2.5'>
      <AssistantTile />
      <p className='min-w-0 flex-1 pt-1 text-sm leading-relaxed'>{text}</p>
    </div>
  );
}

function CannedReply({ text }: { text: string }) {
  return (
    <>
      <PersonBubble text={text} />
      <div className='flex items-start gap-2.5'>
        <AssistantTile />
        <p className='text-muted-foreground min-w-0 flex-1 pt-1 text-sm leading-relaxed'>
          {FOLLOW_UP_REPLY}
        </p>
      </div>
    </>
  );
}

function Line({ line }: { line: ChatLine }) {
  if (line.from === 'person') {
    return <PersonBubble text={line.text} />;
  }
  return <AssistantLine text={line.text} />;
}

type EmptyChatProps = {
  suggestions: string[];
  onSuggest: (text: string) => void;
};

function EmptyChat({ suggestions, onSuggest }: EmptyChatProps) {
  return (
    <div className='m-auto flex w-full max-w-md flex-col items-center gap-5 py-6 text-center'>
      <div className='flex flex-col items-center gap-1.5'>
        <h2 className='text-base font-semibold text-balance'>
          Ask about your shipments
        </h2>
        <p className='text-muted-foreground max-w-xs text-[13px] leading-relaxed text-balance'>
          The plan, every tool call and the cost of the run show in the details
          while the answer is written.
        </p>
      </div>
      <ul
        aria-label='Suggested questions'
        className='flex w-full flex-col gap-1.5'
      >
        {suggestions.map((text) => (
          <li key={text} className='flex'>
            <button
              type='button'
              onClick={() => onSuggest(text)}
              className='bg-foreground/[0.04] hover:bg-foreground/[0.07] focus-visible:ring-ring/25 w-full cursor-pointer rounded-lg px-3 py-2 text-start text-[13px] transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px] active:scale-[0.97]'
            >
              {text}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

type LiveChatProps = {
  state: ChatState;
  pressed: string | null;
  isActive: boolean;
  onDecide: (decision: Decision) => void;
  canShowDetails: boolean;
  onShowDetails: () => void;
  onSuggest: (text: string) => void;
};

function LiveChat({
  state,
  pressed,
  isActive,
  onDecide,
  canShowDetails,
  onShowDetails,
  onSuggest,
}: LiveChatProps) {
  const { stage, question } = state;
  if (question === null) {
    return <EmptyChat suggestions={LIVE_SUGGESTIONS} onSuggest={onSuggest} />;
  }
  const requestView = requestViewOf(state);
  const showsRequest = requestView !== 'none';
  const showsPlan = state.plan.length > 0;
  const showsAnswer = showsAnswerOf(state);
  const isAnswering = stage === 'answering';
  const isStoppedMidAnswer =
    stage === 'stopped' && state.stoppedFrom === 'answering';
  const isStreaming = isAnswering || isStoppedMidAnswer;

  return (
    <>
      <PersonBubble text={question} />
      <div className='flex items-start gap-2.5'>
        <AssistantTile />
        <div className='flex min-w-0 flex-1 flex-col gap-3 pt-1'>
          <span className='sr-only'>{ASSISTANT.name}</span>
          <ThinkingBlock
            stage={stage}
            isActive={isActive}
            startedAt={state.startedAt}
            thoughtEndedAt={state.thoughtEndedAt}
          />
          {showsPlan && (
            <WorkLine
              plan={state.plan}
              stage={stage}
              startedAt={state.startedAt}
              endedAt={state.endedAt}
              canShowDetails={canShowDetails}
              onShowDetails={onShowDetails}
            />
          )}
          {showsRequest && (
            <ApprovalCard
              view={requestView}
              pressed={pressed}
              onDecide={onDecide}
            />
          )}
          {showsAnswer && (
            <CitedAnswer
              isStreaming={isStreaming}
              isRunning={isAnswering && isActive}
              demoLitSource={state.demoLitSource}
            />
          )}
        </div>
      </div>
      {state.followUps.map((text, index) => (
        <CannedReply key={index} text={text} />
      ))}
    </>
  );
}

type ThreadProps = LiveChatProps;

export function Thread(props: ThreadProps) {
  const { scrollerRef, contentRef, updatePinned } = useFollowBottom();
  const { activeId, newLines } = props.state;
  const isLive = activeId === LIVE_ID;
  const isNew = activeId === NEW_ID;
  const isPast = !isLive && !isNew;
  const hasNewLines = newLines.length > 0;

  return (
    <div
      ref={scrollerRef}
      onScroll={updatePinned}
      className='min-h-0 flex-1 overflow-y-auto'
    >
      <div
        ref={contentRef}
        className='mx-auto flex min-h-full w-full max-w-2xl flex-col gap-5 px-4 py-5'
      >
        {isLive && <LiveChat {...props} />}
        {isNew && !hasNewLines && (
          <EmptyChat
            suggestions={NEW_SUGGESTIONS}
            onSuggest={props.onSuggest}
          />
        )}
        {isNew &&
          newLines.map((text, index) => (
            <CannedReply key={index} text={text} />
          ))}
        {isPast &&
          chatOf(activeId).lines.map((line, index) => (
            <Line key={index} line={line} />
          ))}
      </div>
    </div>
  );
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import {
  elapsedOf,
  formatDuration,
  type CallStatus,
} from '@/registry/ndeko/lib/agent-run';
import { CircleXIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { PLAN, planSeedOf } from './data';
import type { PlanRun, Stage, StepStatus } from './session';

const TITLES = PLAN.map((seed) => seed.title);

const SEGMENT_TONE: Record<StepStatus, string> = {
  upcoming: 'bg-foreground/10',
  running: 'bg-primary/45 animate-pulse',
  waiting: 'bg-warning',
  done: 'bg-primary',
  skipped: 'bg-foreground/10',
};

const STEP_WORD: Record<StepStatus, string> = {
  upcoming: 'to do',
  running: 'running',
  waiting: 'waiting on you',
  done: 'done',
  skipped: 'skipped',
};

function currentRunOf(plan: PlanRun[]) {
  const live = plan.find((run) => run.status === 'running');
  if (live) {
    return live;
  }
  return plan.find((run) => run.status === 'waiting');
}

function titleOf(plan: PlanRun[], stage: Stage, duration: string) {
  if (stage === 'done') {
    return `Worked for ${duration}`;
  }
  if (stage === 'declined') {
    return 'Run stopped at the request';
  }
  if (stage === 'stopped') {
    return 'Stopped by you';
  }
  const current = currentRunOf(plan);
  if (!current) {
    return 'Working';
  }
  return planSeedOf(current.id).title;
}

function isClockRunning(stage: Stage) {
  return stage === 'working' || stage === 'answering';
}

function markOf(stage: Stage): CallStatus {
  if (stage === 'asking') {
    return 'waiting';
  }
  if (stage === 'done') {
    return 'done';
  }
  return 'running';
}

type WorkLineProps = {
  plan: PlanRun[];
  stage: Stage;
  startedAt?: number;
  endedAt?: number;
  /** False while the details are already on screen. */
  canShowDetails: boolean;
  onShowDetails: () => void;
};

export function WorkLine({
  plan,
  stage,
  startedAt,
  endedAt,
  canShowDetails,
  onShowDetails,
}: WorkLineProps) {
  const span = { startedAt, endedAt };
  const elapsed = elapsedOf(span, endedAt ?? 0);
  const duration = formatDuration(elapsed);
  const title = titleOf(plan, stage, duration);
  const isHalted = stage === 'declined' || stage === 'stopped';
  const isWaiting = stage === 'asking';

  return (
    <div className='flex flex-col gap-2 px-1'>
      <div className='flex h-7 items-center gap-2 text-[13px]'>
        {!isHalted && <CallStatusMark status={markOf(stage)} />}
        {isHalted && (
          <CircleXIcon className='text-muted-foreground size-4 shrink-0' />
        )}
        <span className='min-w-0 truncate font-medium'>
          <WordRoll text={title} labels={TITLES} />
        </span>
        {isClockRunning(stage) && (
          <LiveDuration
            item={span}
            isRunning
            className='text-muted-foreground w-10 shrink-0 text-xs'
          />
        )}
        {isWaiting && (
          <span className='text-warning-foreground shrink-0 text-xs'>
            Waiting on you
          </span>
        )}
        {canShowDetails && (
          <Button
            type='button'
            variant='ghost'
            size='sm'
            onClick={onShowDetails}
            className='text-muted-foreground ms-auto h-6 shrink-0 px-2'
          >
            Run details
          </Button>
        )}
      </div>
      <ol aria-label='Steps of the run' className='flex gap-1'>
        {plan.map((run) => {
          const seed = planSeedOf(run.id);
          return (
            <li
              key={run.id}
              className={cn(
                'h-1 min-w-0 flex-1 rounded-full transition-colors duration-300',
                SEGMENT_TONE[run.status]
              )}
            >
              <span className='sr-only'>
                {seed.title}, {STEP_WORD[run.status]}
              </span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}
